//! Bit-for-bit equivalence tests between the Rust `pricing` module and the
//! Solidity `PricingLibrary` (libraries/PricingLibrary.sol).
//!
//! Truth values are generated by
//! `limit-orders-smartcontracts/test/PricingLibraryVectors.t.sol` and
//! committed to `test_vectors/pricing_vectors.ndjson` (one JSON object per
//! line). To regenerate:
//!
//! ```sh
//! cd limit-orders-smartcontracts
//! rm -f test/vectors/pricing_vectors.ndjson
//! forge test --match-contract PricingLibraryVectors
//! # Forge runs the chunked tests in non-deterministic order, so the raw
//! # NDJSON's line ordering varies per run. Content is fully deterministic.
//! # Sort to get a byte-stable file before committing.
//! LC_ALL=C sort -o test/vectors/pricing_vectors.ndjson \
//!                  test/vectors/pricing_vectors.ndjson
//! cp test/vectors/pricing_vectors.ndjson \
//!    ../contracts/limit-order-engine/test_vectors/pricing_vectors.ndjson
//! ```
//!
//! The Solidity reference uses `uint256` for all inputs/outputs. The Rust
//! port uses `i128` but the values exchanged here all fit in `i128`.
//! Negative `implied_rate` cannot be expressed in Solidity, so it is not
//! covered by these vectors; the `< 0` check in `yt_price_in_underlying` is
//! validated separately in `test.rs`.

extern crate std;

use std::string::String;

use serde::Deserialize;
use soroban_sdk::Env;

use crate::pricing::{pt_price_in_underlying, yt_price_in_underlying};

const VECTORS: &str = include_str!("../test_vectors/pricing_vectors.ndjson");

#[derive(Deserialize)]
struct Vector {
    #[serde(rename = "fn")]
    func: String,
    label: String,
    implied_rate: String,
    time_to_maturity: String,
    future_pt_value: String,
    expected: String,
}

fn parse_i128(s: &str, label: &str, field: &str) -> i128 {
    s.parse::<i128>().unwrap_or_else(|e| {
        panic!("vector {label}: field `{field}` = {s:?} does not fit in i128 ({e})")
    })
}

#[test]
fn pricing_library_vectors() {
    let env = Env::default();
    // Each row drives ~5 I256 ops through the Soroban host. With ~21k rows
    // the default per-test budget is blown; lift it for the run.
    env.cost_estimate().budget().reset_unlimited();

    let mut total: usize = 0;
    let mut pt_count: usize = 0;
    let mut yt_count: usize = 0;

    for (idx, line) in VECTORS.lines().enumerate() {
        if line.trim().is_empty() {
            continue;
        }
        let line_no = idx + 1;
        let v: Vector = serde_json::from_str(line)
            .unwrap_or_else(|e| panic!("line {line_no}: invalid JSON: {e} ({line:?})"));

        let implied_rate = parse_i128(&v.implied_rate, &v.label, "implied_rate");
        let time_to_maturity = parse_i128(&v.time_to_maturity, &v.label, "time_to_maturity");
        let future_pt_value = parse_i128(&v.future_pt_value, &v.label, "future_pt_value");
        let expected = parse_i128(&v.expected, &v.label, "expected");

        let actual = match v.func.as_str() {
            "pt_price" => {
                pt_count += 1;
                pt_price_in_underlying(&env, implied_rate, time_to_maturity, future_pt_value)
            }
            "yt_price" => {
                yt_count += 1;
                yt_price_in_underlying(&env, implied_rate, time_to_maturity, future_pt_value)
            }
            other => panic!("vector {} (line {line_no}): unknown fn {other:?}", v.label),
        };

        assert_eq!(
            actual,
            expected,
            "vector {} (line {line_no}): fn={} implied_rate={} time_to_maturity={} future_pt_value={} \
             — Rust returned {}, Solidity returned {} (diff {})",
            v.label,
            v.func,
            implied_rate,
            time_to_maturity,
            future_pt_value,
            actual,
            expected,
            actual - expected,
        );
        total += 1;
    }

    assert!(
        total > 0,
        "no vectors parsed — is test_vectors/pricing_vectors.ndjson empty?"
    );
    assert!(pt_count > 0, "no pt_price vectors");
    assert!(yt_count > 0, "no yt_price vectors");
    std::println!(
        "pricing_library_vectors: validated {total} rows ({pt_count} pt_price, {yt_count} yt_price)"
    );
}
